mapper.sql:
SELECT qn.ID AS id, qn.create_user_id AS createUserId, qn.create_user_name AS createUserName, qn.create_time AS createTime, qn.is_deleted AS isDeleted, qn.approve_status AS approveStatus, qn.approve_time AS approveTime, qn.approve_user_id AS approveUserId, qn.approve_user_name AS approveUserName, qn.code AS code, qn.qc_warehouse_id AS qcWarehouseId, qn.putaway_warehouse_id AS putawayWarehouseId, qn.qc_type AS qcType, qn.qc_status AS qcStatus, qn.qc_timeliness AS qcTimeliness, qn.remark AS remark, qn.invalid_status AS invalidStatus, qn.invalid_remark AS invalidRemark, qnd.id AS detailId, qnd.sku_id AS skuId, qnd.sku_no AS skuNo, qnd.product_name AS productName, qnd.qc_notice_qty AS qcNoticeQty, qnd.qc_qty AS qcQty, qnd.qc_diff_qty AS qcDiffQty, qnd.qc_good_qty AS qcGoodQty, qnd.qc_bad_qty AS qcBadQty, qnd.putaway_qty AS putawayQty, qnd.bad_desc AS badDesc, qnd.qc_user_id AS qcUserId, qnd.qc_user_name AS qcUserName, qnd.qc_problem_dict AS qcProblemDict, qnd.qc_status AS qcDetailStatus, qnd.qc_date AS qcDate, qnd.putaway_status AS putawayStatus, qnd.putaway_date AS putawayDate, qn.source_id as sourceId, qn.source_code as sourceCode, qn.source_type as sourceType, qn.purchase_order_id as purchaseOrderId, qn.purchase_order_code as purchaseOrderCode, qn.supplier_id as supplierId FROM qc_notice AS qn LEFT JOIN qc_notice_detail AS qnd ON qn.ID = qnd.main_id LEFT JOIN qc_info AS qi on qi.source_detail_id = qnd.id and qi.is_deleted = FALSE WHERE ${params.sqlMap.default} AND qn.is_deleted = FALSE AND qnd.is_deleted = FALSE
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
qn.create_time desc

mapper.select:
SELECT qn.approve_status AS tabFlag, count(*) AS count FROM qc_notice as qn WHERE qn.is_deleted=FALSE and qn.approve_status in ('waitSubmit','approveIng','reject')
${params.permissionSql}
GROUP BY qn.approve_status

SELECT qn.qc_status AS tabFlag, count(*) AS count FROM qc_notice as qn WHERE qn.is_deleted=FALSE and qn.approve_status = 'approve'
${params.permissionSql}
GROUP BY qn.qc_status

SELECT qn.ID AS id, qn.code AS code, qn.qc_type AS qcType, qn.qc_status AS qcStatus, qn.qc_warehouse_id AS qcWarehouseId, qnd.id AS detailId, qnd.sku_id AS skuId, qnd.sku_no AS skuNo, qnd.product_name AS productName, qnd.qc_notice_qty AS qcNoticeQty, qnd.qc_qty AS qcQty, qnd.qc_diff_qty AS qcDiffQty, qnd.qc_good_qty AS qcGoodQty, qnd.qc_bad_qty AS qcBadQty, qnd.putaway_qty AS putawayQty, qnd.bad_desc AS badDesc, qnd.qc_problem_dict AS qcProblemDict, qnd.qc_date AS qcDate FROM qc_notice AS qn LEFT JOIN qc_notice_detail AS qnd ON qn.ID = qnd.main_id WHERE qn.is_deleted = FALSE AND qn.approve_status = 'approve' AND qnd.is_deleted = FALSE and qnd.qc_status = 'wait' AND qn.id IN
#{id}
ORDER BY qn.code
